def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    my_d_total = 0
    opp_d_total = 0
    for a, b in history:
        if a == 'D':
            my_d_total += 1
        if b == 'D':
            opp_d_total += 1
    opp_c_total = n - opp_d_total

    if opp_c_total == 0:
        return 'D'

    my_d_next = 0
    my_d_next_d = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            my_d_next += 1
            if history[i + 1][1] == 'D':
                my_d_next_d += 1

    if my_d_next >= 2:
        punish_rate = my_d_next_d / my_d_next
    else:
        punish_rate = 0.5

    if opp_d_total == 0:
        if my_d_total > 0:
            return 'D'
        if n >= 90 and rng.random() < 0.30:
            return 'D'
        if n >= 20 and rng.random() < 0.07:
            return 'D'
        return 'C'

    opp_d_streak = 0
    for a, b in reversed(history):
        if b == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for a, b in reversed(history):
        if a == 'D':
            my_d_streak += 1
        else:
            break

    dd_streak = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'D':
            dd_streak += 1
        else:
            break

    opp_d_recent5 = 0
    for a, b in history[-5:]:
        if b == 'D':
            opp_d_recent5 += 1

    lean = (opp_c_total * 7 >= opp_d_total * 10)
    nonpunisher = (my_d_next >= 2 and my_d_next_d == 0)

    if my_last == 'C' and opp_last == 'D':
        if opp_d_streak >= 2:
            return 'D'
        if history[-2][0] == 'D':
            return 'C'
        if opp_d_total > opp_c_total:
            return 'D'
        return 'D'

    if my_last == 'D' and opp_last == 'C':
        if nonpunisher and opp_d_recent5 == 0:
            return 'D'
        if punish_rate >= 0.45:
            return 'C'
        if opp_d_total > opp_c_total and opp_d_recent5 >= 2:
            return 'D'
        if n >= 96 and lean and opp_d_recent5 == 0 and rng.random() < 0.35:
            return 'D'
        return 'C'

    if my_last == 'C' and opp_last == 'C':
        if n == 98 and (nonpunisher or (opp_d_total <= 1 and my_d_total > 0)):
            return 'D'
        if nonpunisher and opp_d_recent5 == 0 and lean:
            return 'D'
        if opp_d_recent5 == 0 and opp_c_total >= opp_d_total * 3:
            if n >= 30 and rng.random() < 0.04:
                return 'D'
        if opp_d_total > opp_c_total and opp_d_recent5 >= 3:
            return 'D'
        return 'C'

    if my_last == 'D' and opp_last == 'D':
        if lean and dd_streak >= 3 and opp_d_streak <= 5:
            return 'C'
        if lean and dd_streak >= 5 and opp_d_streak <= 7:
            return 'C'
        if my_d_streak >= 10 and opp_d_streak >= 15 and rng.random() < 0.05:
            return 'C'
        return 'D'

    return 'C'
